package server

// Authorization policies for the sessions routes. See route_auth_policy_test.go
// for the classes; routePolicyFile says which file a new route belongs in.
func init() {
	declareRoutePolicies(map[string]routePolicy{
		"POST /api/v1/sessions/chat":                                                    object("authorizeOrgMember", "authorizeUserToApp", "authorizeUserToSession"),
		"GET /api/v1/sessions":                                                          object("authorizeOrgMember", "authorizeUserToProjectByID"),
		"DELETE /api/v1/sessions/{id}":                                                  object("authorizeUserToSession"),
		"PUT /api/v1/sessions/{id}":                                                     object("authorizeUserToSession"),
		"PATCH /api/v1/sessions/{id}/archive":                                           object("authorizeUserToSession"),
		"POST /api/v1/sessions/{id}/clear":                                              object("authorizeUserToSession"),
		"GET /api/v1/sessions/{id}/interactions":                                        object("authorizeUserToSession"),
		"GET /api/v1/sessions/{id}/usage":                                               object("authorizeUserToSession"),
		"GET /api/v1/sessions/{id}/interactions/{interaction_id}":                       object("authorizeUserToSession"),
		"POST /api/v1/sessions/{id}/interactions/{interaction_id}/feedback":             object("authorizeUserToSession"),
		"GET /api/v1/sessions/{id}/step-info":                                           object("authorizeUserToSession"),
		"GET /api/v1/sessions/{id}/rdp-connection":                                      object("authorizeUserToSession"),
		"GET /api/v1/sessions/{id}/sandbox-state":                                       object("authorizeUserToSession"),
		"GET /api/v1/sessions/{id}/operator-access":                                     object("authorizeUserToProjectByID", "authorizeUserToSession"),
		"POST /api/v1/sessions/{id}/resume":                                             object("authorizeUserToSession"),
		"POST /api/v1/sessions/{id}/messages":                                           object("authorizeUserToSession"),
		"POST /api/v1/sessions/{id}/ensure-agent":                                       object("authorizeUserToSession"),
		"POST /api/v1/sessions/{id}/fork":                                               object("authorizeUserToSession"),
		"POST /api/v1/sessions/{id}/switch-agent":                                       object("authorizeUserToSession"),
		"GET /api/v1/sessions/{id}/execution-config":                                    object("authorizeUserToSession"),
		"PATCH /api/v1/sessions/{id}/execution-config":                                  object("authorizeUserToSession"),
		"POST /api/v1/sessions/{id}/agent-config-applied":                               object("authorizeUserToSession"),
		"POST /api/v1/sessions/{id}/agent-startup-error":                                object("authorizeUserToSession"),
		"GET /api/v1/sessions/{id}/workspace-status":                                    object("authorizeUserToSession"),
		"DELETE /api/v1/sessions/{id}/stop-external-agent":                              object("authorizeUserToSession"),
		"POST /api/v1/sessions/{id}/cancel":                                             object("authorizeUserToSession"),
		"POST /api/v1/sessions/{id}/restart-agent":                                      object("authorizeUserToSession"),
		"POST /api/v1/sessions/{id}/foreground-thread":                                  object("authorizeUserToSession"),
		"GET /api/v1/sessions/{id}/output":                                              object("authorizeUserToSession"),
		"GET /api/v1/sessions/{id}/terminal":                                            object("loadAuthorizedTerminalSession"),
		"GET /api/v1/sessions/{id}/terminal/sessions":                                   object("loadAuthorizedTerminalSession"),
		"DELETE /api/v1/sessions/{id}/terminal/sessions/{terminal_session}":             object("loadAuthorizedTerminalSession"),
		"GET /api/v1/sessions/{id}/preview-tokens":                                      object("authorizeUserToSession"),
		"POST /api/v1/sessions/{id}/preview-tokens":                                     object("authorizeUserToSession"),
		"POST /api/v1/sessions/{id}/preview-tokens/{token_id}/rotate":                   object("authorizeUserToSession"),
		"DELETE /api/v1/sessions/{id}/preview-tokens/{token_id}":                        object("authorizeUserToSession"),
		"GET /api/v1/sessions/{id}/toc":                                                 object("authorizeUserToSession"),
		"GET /api/v1/sessions/{id}/turns/{turn}":                                        object("authorizeUserToSession"),
		"GET /api/v1/sessions/{id}/search":                                              object("authorizeUserToSession"),
		"GET /api/v1/prompt-history":                                                    object("authorizeUserToPromptQueue"),
		"POST /api/v1/prompt-history/sync":                                              object("authorizeSyncEntryTargets", "authorizeUserToPromptQueue"),
		"DELETE /api/v1/prompt-history/{id}":                                            noAuthzHelper("inline owner check: prompt.UserID == user.ID"),
		"GET /api/v1/sessions/{id}/zed-config":                                          object("authorizeSessionSandboxConfig").alsoRunner(),
		"POST /api/v1/sessions/{id}/zed-config/user":                                    object("authorizeSessionSandboxConfig").alsoRunner(),
		"GET /api/v1/sessions/{id}/zed-settings":                                        object("authorizeSessionSandboxConfig"),
		"POST /api/v1/claude-subscriptions":                                             object("createClaudeSubscriptionFrom"),
		"GET /api/v1/claude-subscriptions":                                              user(),
		"GET /api/v1/claude-subscriptions/models":                                       user(),
		"GET /api/v1/claude-subscriptions/{id}":                                         object("authorizeOrgOwner"),
		"DELETE /api/v1/claude-subscriptions/{id}":                                      object("authorizeOrgOwner"),
		"PUT /api/v1/claude-subscriptions/{id}/delegation":                              object("authorizeOrgOwner"),
		"POST /api/v1/claude-subscriptions/oauth/start":                                 user(),
		"POST /api/v1/claude-subscriptions/oauth/complete":                              object("createClaudeSubscriptionFrom"),
		"GET /api/v1/sessions/{id}/claude-credentials":                                  noAuthzHelper("inline: session owner, the session's own key, or the runner token; then canUseSessionAgentCredential").alsoRunner(),
		"PUT /api/v1/sessions/{id}/claude-credentials":                                  noAuthzHelper("inline: session owner, the session's own key, or the runner token; then canUseSessionAgentCredential").alsoRunner(),
		"POST /api/v1/codex-subscriptions":                                              object("authorizeOrgOwner"),
		"GET /api/v1/codex-subscriptions":                                               user(),
		"GET /api/v1/codex-subscriptions/{id}":                                          object("authorizeCodexSubscription"),
		"DELETE /api/v1/codex-subscriptions/{id}":                                       object("authorizeCodexSubscription"),
		"POST /api/v1/codex-subscriptions/start-login":                                  object("authorizeOrgOwner"),
		"GET /api/v1/codex-subscriptions/poll-login/{sessionId}":                        noAuthzHelper("inline owner check: login session.Owner == user.ID"),
		"DELETE /api/v1/codex-subscriptions/login/{sessionId}":                          noAuthzHelper("inline owner check: login session.Owner == user.ID"),
		"GET /api/v1/sessions/{id}/codex-credentials":                                   noAuthzHelper("inline: session owner, the session's own key, or the runner token; then canUseSessionAgentCredential").alsoRunner(),
		"PUT /api/v1/sessions/{id}/codex-credentials":                                   noAuthzHelper("inline: session owner, the session's own key, or the runner token; then canUseSessionAgentCredential").alsoRunner(),
		"GET /api/v1/external-agents/sync":                                              user().alsoRunner(),
		"GET /api/v1/external-agents/{sessionID}/screenshot":                            object("authorizeDesktopID"),
		"GET /api/v1/external-agents/{sessionID}/clipboard":                             object("authorizeUserToSession"),
		"POST /api/v1/external-agents/{sessionID}/clipboard":                            object("authorizeUserToSession"),
		"POST /api/v1/external-agents/{sessionID}/upload":                               object("authorizeUserToSession"),
		"GET /api/v1/external-agents/{sessionID}/file":                                  object("authorizeUserToSession"),
		"POST /api/v1/external-agents/{sessionID}/exec":                                 object("authorizeUserToSession"),
		"GET /api/v1/external-agents/{sessionID}/ws/input":                              object("authorizeDesktopID"),
		"GET /api/v1/external-agents/{sessionID}/ws/stream":                             object("authorizeDesktopID"),
		"POST /api/v1/external-agents/{sessionID}/configure-pending-session":            noAuthzHelper("no-op kept for API compatibility; touches nothing"),
		"GET /api/v1/external-agents/{sessionID}/workspace-review":                      object("authorizeWorkspaceReviewRequest"),
		"GET /api/v1/external-agents/{sessionID}/workspace-review/turn/{interactionID}": object("authorizeWorkspaceReviewRequest"),
		"GET /api/v1/external-agents/{sessionID}/workspace-files":                       object("proxyAuthorizedWorkspaceGETWithAction"),
		"GET /api/v1/external-agents/{sessionID}/workspace-file":                        object("proxyAuthorizedWorkspaceGET"),
		"GET /api/v1/external-agents/{sessionID}/workspace-file/download":               object("authorizeWorkspaceReviewRequest"),
		"PUT /api/v1/external-agents/{sessionID}/workspace-file":                        object("authorizeWorkspaceReviewRequest"),
		"GET /api/v1/external-agents/{sessionID}/workspace-skills":                      object("proxyAuthorizedWorkspaceGET"),
		"GET /api/v1/external-agents/{sessionID}/workspaces":                            object("authorizeUserToSession"),
		"POST /api/v1/external-agents/{sessionID}/command":                              object("authorizeUserToSession"),
		"GET /api/v1/attention-events":                                                  user(),
		"POST /api/v1/attention-events/dismiss-all":                                     user(),
		"PUT /api/v1/attention-events/{id}":                                             noAuthzHelper("inline owner check: event.UserID == user.ID"),
		"POST /api/v1/zed/events":                                                       object("authorizeZedSpecTask"),
		"POST /api/v1/zed/instances/{instanceId}/threads/{threadId}/events":             object("authorizeZedSpecTask"),
		"POST /api/v1/zed/instances/{instanceId}/heartbeat":                             object("authorizeZedSpecTask"),
		"POST /api/v1/zed/threads/{threadId}/activity":                                  object("authorizeZedSpecTask"),
		"POST /api/v1/work-sessions/{sessionId}/zed-thread":                             object("authorizeUserToZedSpecTask"),
		"GET /api/v1/sessions/{id}":                                                     handlerAuth("extractMiddleware; handler requires a user and authorizes the session").authz("authorizeUserToSession"),
		"GET /api/v1/sessions/{id}/visualization":                                       handlerAuth("extractMiddleware (cookie for iframes); handler authorizes the session").authz("authorizeUserToSession"),
		"ANY /api/v1/ws/external-agent-runner":                                          handlerAuth("runner token in the access_token query parameter; a per-runner token only for its own runnerid (authorizeRunnerIdentity)"),
		"ANY /api/v1/ws/user":                                                           handlerAuth("session cookie or API key resolved in the handler; the runner token is refused; session ownership checked before subscribing"),
		"ANY /api/v1/ws/runner":                                                         handlerAuth("runner token resolved in the handler; a per-runner token only for its own runnerid (authorizeRunnerIdentity)"),
	})
}
